-- See database migration applied on 2026-08-31.
-- Organizer bank-soal tier guards, essay similarity, daily check-in defaults/overrides,
-- special event themes, referral verification and hourly anti-cheat cron.

ALTER TABLE public.plan_entitlements ADD COLUMN IF NOT EXISTS config jsonb DEFAULT '{}'::jsonb;
INSERT INTO public.plan_entitlements(plan_code,capability,limit_value,config) SELECT 'PREMIUM','essay_ai_assessment',1,'{"enabled":true}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.plan_entitlements WHERE plan_code='PREMIUM' AND capability='essay_ai_assessment');
INSERT INTO public.plan_entitlements(plan_code,capability,limit_value,config) SELECT 'PRO','twibbon_canvas',1,'{"enabled":true}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.plan_entitlements WHERE plan_code='PRO' AND capability='twibbon_canvas');
INSERT INTO public.plan_entitlements(plan_code,capability,limit_value,config) SELECT 'PREMIUM','twibbon_canvas',1,'{"enabled":true}'::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.plan_entitlements WHERE plan_code='PREMIUM' AND capability='twibbon_canvas');

ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS category_codes text[];
ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS excluded_category_codes text[];
ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS target_grades text[];
ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS excluded_grades text[];
ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS twibbon_mode text DEFAULT 'external';
ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS twibbon_frame_url text;
ALTER TABLE public.competitions ADD COLUMN IF NOT EXISTS twibbon_frame_public_id text;

DROP FUNCTION IF EXISTS public.save_question_with_options(uuid,uuid,text,text,numeric,boolean,integer,text,jsonb,jsonb);
CREATE OR REPLACE FUNCTION public.save_question_with_options(p_question_id uuid,p_question_bank_id uuid,p_type text,p_prompt text,p_points numeric DEFAULT 1,p_required boolean DEFAULT true,p_display_order integer DEFAULT 0,p_status text DEFAULT 'DRAFT',p_config jsonb DEFAULT '{}'::jsonb,p_options jsonb DEFAULT '[]'::jsonb) RETURNS public.questions LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','private' AS $$ DECLARE v_uid uuid:=auth.uid();v_question public.questions%ROWTYPE;v_org uuid;v_plan text;v_option jsonb;v_count int;v_correct int; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF; SELECT organizer_id INTO v_org FROM public.question_banks WHERE id=p_question_bank_id; IF v_org IS NULL THEN RAISE EXCEPTION 'BANK_NOT_FOUND'; END IF; IF NOT (EXISTS(SELECT 1 FROM public.organizer_members om WHERE om.organizer_id=v_org AND om.user_id=v_uid AND om.status='ACTIVE') OR EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=v_uid AND ur.role='admin' AND ur.is_active=true)) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; SELECT op.plan_code INTO v_plan FROM public.organizer_plans op WHERE op.organizer_id=v_org AND op.is_active=true AND op.starts_at<=now() AND (op.ends_at IS NULL OR op.ends_at>now()) ORDER BY op.starts_at DESC,op.created_at DESC LIMIT 1; IF lower(p_type) IN('essay','long-answer') AND (coalesce(p_config,'{}'::jsonb) ? 'answer_key' OR coalesce(p_config,'{}'::jsonb)->'ai_assessment'->>'enabled'='true') THEN IF NOT EXISTS(SELECT 1 FROM public.plan_entitlements pe WHERE pe.plan_code=v_plan AND pe.capability='essay_ai_assessment' AND coalesce(pe.limit_value,0)>0) THEN RAISE EXCEPTION 'PREMIUM_REQUIRED'; END IF; END IF; IF lower(p_type) IN('multiple-choice','mcq') THEN v_count:=jsonb_array_length(coalesce(p_options,'[]'::jsonb));IF v_count<3 OR v_count>6 THEN RAISE EXCEPTION 'MCQ_OPTIONS_3_6';END IF;SELECT count(*) INTO v_correct FROM jsonb_array_elements(coalesce(p_options,'[]'::jsonb))x WHERE coalesce((x->>'is_correct')::boolean,false);IF v_correct<1 THEN RAISE EXCEPTION 'MCQ_CORRECT_REQUIRED';END IF;ELSIF lower(p_type) IN('true-false','true_false') THEN p_options:='[{"label":"Benar","value":"Benar","is_correct":false,"display_order":0},{"label":"Salah","value":"Salah","is_correct":false,"display_order":1}]'::jsonb;END IF;IF p_question_id IS NULL THEN INSERT INTO public.questions(question_bank_id,type,prompt,points,required,display_order,status,config)VALUES(p_question_bank_id,p_type,p_prompt,p_points,p_required,p_display_order,p_status,p_config)RETURNING * INTO v_question;ELSE UPDATE public.questions SET question_bank_id=p_question_bank_id,type=p_type,prompt=p_prompt,points=p_points,required=p_required,display_order=p_display_order,status=p_status,config=p_config,updated_at=now() WHERE id=p_question_id RETURNING * INTO v_question;IF NOT FOUND THEN RAISE EXCEPTION 'QUESTION_NOT_FOUND';END IF;END IF;DELETE FROM public.question_options WHERE question_id=v_question.id;FOR v_option IN SELECT * FROM jsonb_array_elements(coalesce(p_options,'[]'::jsonb)) LOOP INSERT INTO public.question_options(question_id,label,value,is_correct,display_order)VALUES(v_question.id,coalesce(v_option->>'label',''),coalesce(v_option->>'value',v_option->>'label',''),coalesce((v_option->>'is_correct')::boolean,false),coalesce((v_option->>'display_order')::int,0));END LOOP;RETURN v_question;END; $$;

CREATE OR REPLACE FUNCTION public.calculate_essay_similarity(p_answer text,p_key text) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ WITH a AS(SELECT DISTINCT regexp_replace(lower(x),'[^[:alnum:]_]+','','g') tok FROM regexp_split_to_table(coalesce(p_answer,''),'\s+')x WHERE length(regexp_replace(lower(x),'[^[:alnum:]_]+','','g'))>0),b AS(SELECT DISTINCT regexp_replace(lower(x),'[^[:alnum:]_]+','','g')tok FROM regexp_split_to_table(coalesce(p_key,''),'\s+')x WHERE length(regexp_replace(lower(x),'[^[:alnum:]_]+','','g'))>0),u AS(SELECT count(*)n FROM(SELECT tok FROM a UNION SELECT tok FROM b)s),i AS(SELECT count(*)n FROM(SELECT tok FROM a INTERSECT SELECT tok FROM b)s) SELECT CASE WHEN(SELECT n FROM u)=0 THEN 0::numeric ELSE round(100.0*(SELECT n FROM i)::numeric/(SELECT n FROM u)::numeric,2)END; $$;
CREATE OR REPLACE FUNCTION public.get_essay_similarity(p_answer text,p_key text) RETURNS numeric LANGUAGE sql IMMUTABLE AS $$ SELECT public.calculate_essay_similarity(p_answer,p_key); $$;

CREATE TABLE IF NOT EXISTS public.daily_checkin_settings(id boolean PRIMARY KEY DEFAULT true,regular_xp integer NOT NULL DEFAULT 50,regular_coin integer NOT NULL DEFAULT 10,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES auth.users(id));
INSERT INTO public.daily_checkin_settings(id) VALUES(true) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS public.daily_checkin_overrides(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),checkpoint_key text NOT NULL UNIQUE,checkpoint_date date,day_number integer,reward_type text NOT NULL CHECK(reward_type IN('XP','COIN','BADGE','FEATURE')),reward_amount numeric NOT NULL DEFAULT 0,reward_payload jsonb NOT NULL DEFAULT '{}'::jsonb,sparkle boolean NOT NULL DEFAULT false,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.daily_checkin_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,description text,icon_url text,icon_public_id text,frame_style text NOT NULL DEFAULT 'green-gold',is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>=start_date));
CREATE TABLE IF NOT EXISTS public.daily_checkins(user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,checkin_date date NOT NULL,reward_type text NOT NULL,reward_amount numeric NOT NULL DEFAULT 0,streak_day integer NOT NULL DEFAULT 1,event_id uuid REFERENCES public.daily_checkin_events(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,checkin_date));
CREATE INDEX IF NOT EXISTS idx_daily_checkin_events_range ON public.daily_checkin_events(start_date,end_date) WHERE is_active=true;
CREATE OR REPLACE FUNCTION public.resolve_daily_checkin_reward(p_date date DEFAULT current_date,p_day_number integer DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public','private' AS $$ DECLARE s public.daily_checkin_settings;o public.daily_checkin_overrides;e public.daily_checkin_events;r jsonb;BEGIN SELECT * INTO s FROM public.daily_checkin_settings WHERE id=true;SELECT * INTO o FROM public.daily_checkin_overrides WHERE is_active=true AND((checkpoint_date IS NOT NULL AND checkpoint_date=p_date)OR(day_number IS NOT NULL AND day_number=p_day_number))ORDER BY CASE WHEN checkpoint_date=p_date THEN 0 ELSE 1 END LIMIT 1;SELECT * INTO e FROM public.daily_checkin_events WHERE is_active=true AND p_date BETWEEN start_date AND end_date ORDER BY start_date DESC LIMIT 1;r:=jsonb_build_object('reward_type',coalesce(o.reward_type,'XP'),'reward_amount',coalesce(o.reward_amount,s.regular_xp),'sparkle',coalesce(o.sparkle,false),'event_id',e.id,'event_name',e.name,'event_description',e.description,'icon_url',e.icon_url,'frame_style',e.frame_style,'regular_xp',s.regular_xp,'regular_coin',s.regular_coin);IF o.id IS NULL AND s.regular_coin>0 THEN r:=r||jsonb_build_object('coin_amount',s.regular_coin);END IF;RETURN r;END; $$;

ALTER TABLE public.referral_events ADD COLUMN IF NOT EXISTS verified_at timestamptz;
ALTER TABLE public.referral_events ADD COLUMN IF NOT EXISTS last_checked_at timestamptz;
ALTER TABLE public.referral_events ADD COLUMN IF NOT EXISTS verified_activity text;
CREATE INDEX IF NOT EXISTS idx_referral_events_pending ON public.referral_events(created_at) WHERE verified_at IS NULL;
CREATE OR REPLACE FUNCTION public.verify_pending_referrals() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','private' AS $$ DECLARE r record;n integer:=0;activity text;ts timestamptz;BEGIN FOR r IN SELECT * FROM public.referral_events WHERE verified_at IS NULL AND created_at>=now()-interval '24 hours' LOOP activity:=null;ts:=null;SELECT 'daily_checkin',created_at INTO activity,ts FROM public.daily_checkins WHERE user_id=r.referred_user_id AND created_at>=r.created_at ORDER BY created_at LIMIT 1;IF activity IS NULL THEN SELECT 'comment',created_at INTO activity,ts FROM public.comments WHERE user_id=r.referred_user_id AND created_at>=r.created_at ORDER BY created_at LIMIT 1;END IF;IF activity IS NULL THEN SELECT 'follow',created_at INTO activity,ts FROM public.follows WHERE follower_id=r.referred_user_id AND created_at>=r.created_at ORDER BY created_at LIMIT 1;END IF;IF activity IS NULL THEN SELECT 'chat',created_at INTO activity,ts FROM public.chat_messages WHERE sender_id=r.referred_user_id AND created_at>=r.created_at ORDER BY created_at LIMIT 1;END IF;IF activity IS NULL THEN SELECT 'daily_task',completed_at INTO activity,ts FROM public.daily_task_claims WHERE user_id=r.referred_user_id AND status='COMPLETED' AND completed_at>=r.created_at ORDER BY completed_at LIMIT 1;END IF;IF activity IS NOT NULL THEN UPDATE public.referral_events SET verified_at=coalesce(ts,now()),verified_activity=activity,status='VERIFIED',last_checked_at=now() WHERE id=r.id;n:=n+1;ELSE UPDATE public.referral_events SET last_checked_at=now() WHERE id=r.id;END IF;END LOOP;RETURN n;END; $$;
CREATE OR REPLACE FUNCTION public.get_my_verified_referrals() RETURNS TABLE(referred_user_id uuid,full_name text,username text,joined_at timestamptz,last_login_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','private' AS $$ SELECT re.referred_user_id,coalesce(p.full_name,p.username,'Pengguna'),p.username,re.created_at,au.last_sign_in_at FROM public.referral_events re JOIN auth.users au ON au.id=re.referred_user_id LEFT JOIN public.profiles p ON p.id=re.referred_user_id WHERE re.referrer_user_id=auth.uid() AND re.verified_at IS NOT NULL ORDER BY re.verified_at DESC; $$;
DO $$ BEGIN CREATE EXTENSION IF NOT EXISTS pg_cron; EXCEPTION WHEN OTHERS THEN NULL; END $$;
DO $$ BEGIN PERFORM cron.unschedule('syka-verify-referrals-hourly'); EXCEPTION WHEN OTHERS THEN NULL; END $$;
DO $$ BEGIN PERFORM cron.schedule('syka-verify-referrals-hourly','0 * * * *','SELECT public.verify_pending_referrals();'); EXCEPTION WHEN OTHERS THEN NULL; END $$;
